name" = 'Underutilized Amazon EBS Volumes' THEN "volume id" WHEN "checkname" = 'Underutilized Amazon Redshift Clusters' THEN "cluster" WHEN "checkname" = 'Amazon EBS Public Snapshots' THEN "volume id" WHEN "checkname" = 'Amazon RDS Public Snapshots' THEN "db instance or cluster id" WHEN "checkname" = 'AWS Lambda Functions with High Error Rates' THEN "function arn" WHEN "checkname" = 'AWS Lambda Functions Using Deprecated Runtimes' THEN "function arn" WHEN "checkid" = 'Wxdfp4B1L1' OR "checkid" = 'Wxdfp4B1L2' OR "checkid" = 'Wxdfp4B1L3' OR "checkid" = 'Wxdfp4B1L4' THEN "workload arn" ELSE (COALESCE("resourceid", '')  || COALESCE(CASE WHEN "accountname" = '' OR "accountname" IS NULL THEN "accountid" ELSE (COALESCE("accountname", '')  || COALESCE(': ', '')  || COALESCE("accountid", '')) END, '')) END AS "Resource Name", from_unixtime(cast(substr(cast(case when regexp_like("timestamp", '^-?\d+$') then cast("timestamp" as bigint) else null end as varchar), 1, 10) AS bigint)) AS "Datetime", CASE WHEN "accountname" = '' OR "accountname" IS NULL THEN "accountid" ELSE (COALESCE("accountname", '')  || COALESCE(': ', '')  || COALESCE("accountid", '')) END AS "Account", CASE WHEN "checkname" = 'Idle Load Balancers' THEN case when regexp_like(REPLACE(REPLACE("estimated monthly savings", '$', ''), ',', ''), '^-?\d+(\.\d*)?$') then cast(REPLACE(REPLACE("estimated monthly savings", '$', ''), ',', '') as double) else null end WHEN "checkname" = 'Amazon RDS Idle DB Instances' THEN case when regexp_like(REPLACE(REPLACE("estimated monthly savings (on demand)", '$', ''), ',', ''), '^-?\d+(\.\d*)?$') then cast(REPLACE(REPLACE("estimated monthly savings (on demand)", '$', ''), ',', '') as double) else null end WHEN "checkname" = 'Low Utilization Amazon EC2 Instances' THEN case when regexp_like(REPLACE(REPLACE("estimated monthly savings", '$', ''), ',', ''), '^-?\d+(\.\d*)?$') then cast(REPLACE(REPLACE("estimated monthly savings", '$', ''), ',', '') as double) else null end WHEN "checkname" = 'Underutilized Amazon EBS Volumes' THEN case when regexp_like(REPLACE(REPLACE("monthly storage cost", '$', ''), ',', ''), '^-?\d+(\.\d*)?$') then cast(REPLACE(REPLACE("monthly storage cost", '$', ''), ',', '') as double) else null end WHEN "checkname" = 'Underutilized Amazon Redshift Clusters' THEN case when regexp_like(REPLACE(REPLACE("estimated monthly savings", '$', ''), ',', ''), '^-?\d+(\.\d*)?$') then cast(REPLACE(REPLACE("estimated monthly savings", '$', ''), ',', '') as double) else null end WHEN "checkname" = 'AWS Lambda Functions with High Error Rates' THEN case when regexp_like(REPLACE(REPLACE("lost daily compute cost", '$', ''), ',', ''), '^-?\d+(\.\d*)?$') then cast(REPLACE(REPLACE("lost daily compute cost", '$', ''), ',', '') as double) else null end * 30 ELSE NULL END AS "Estimated Monthly Savings Numeric", CASE WHEN "status" = 'error' THEN 'Red' WHEN "status" = 'warning' THEN 'Yellow' WHEN "status" = 'ok' THEN 'Green' ELSE "status" END AS "Status", CASE WHEN "category" = 'cost_optimizing' THEN 'Cost Optimizing' WHEN "category" = 'fault_tolerance' THEN 'Fault Tolerance' WHEN "category" = 'security' THEN 'Security' WHEN "category" = 'performance' THEN 'Performance' WHEN "category" = 'service_limits' THEN 'Service Limits' ELSE "category" END AS "Category", (COALESCE("resourceid", '')  || COALESCE(CASE WHEN "accountname" = '' OR "accountname" IS NULL THEN "accountid" ELSE (COALESCE("accountname", '')  || COALESCE(': ', '')  || COALESCE("accountid", '')) END, '')) AS "Resource Id"
FROM "cid_cur"."ta_org_view"

